<?= view('layout/header',['title'=>'Products']) ?><div class="top"><h1>Products</h1><a class="btn" href="<?= site_url('products/new') ?>">Add product</a></div><table><tr><th>Image</th><th>Name</th><th>Price</th><th>Stock</th><th>Actions</th></tr><?php foreach($products as $p): ?><tr><td><?php if($p['image']): ?><img class="thumb" src="<?= base_url('uploads/products/'.$p['image']) ?>"><?php endif ?></td><td><?= esc($p['name']) ?></td><td><?= number_format($p['price'],2) ?></td><td><?= esc($p['stock_quantity']) ?></td><td><a href="<?= site_url('products/edit/'.$p['id']) ?>">Edit</a> <a class="error" href="<?= site_url('products/delete/'.$p['id']) ?>" onclick="return confirm('Delete this product?')">Delete</a></td></tr><?php endforeach ?></table><?= view('layout/footer') ?>
